// src/App.js
import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import LoginPage from "./pages/LoginPage";
import CompanyRegisterForm from "../src/pages/CompanyRegisterForm";
import JobCreatorDashboard from "../src/pages/JobCreatorDashboard";
import JobManagerDashboard from "../src/pages/JobManagerDashboard";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/LoginPage" element={<LoginPage />} />
          <Route path="/CompanyRegisterForm" element={<CompanyRegisterForm />} />
          <Route path="/JobCreatorDashboard" element={<JobCreatorDashboard />} />
          <Route path="/JobManagerDashboard" element={<JobManagerDashboard />} />
          {/* Add other routes if necessary */}
        </Routes>
      </div>
    </Router>
  );
}

export default App;
